<?= $this->extend('layouts/shell') ?>
<?= $this->setVar('entryScript', 'assets/js/admin/app.js') ?>
<?= $this->section('content') ?>
<div id="admin-app" class="workspace" v-cloak>
  <header><div class="eyebrow">Platform administration</div><h1>Onboard a Shop</h1><p>Create the Owner, Tenant, Shop, brand, platform address and Trial in one audited transaction.</p></header>
  <ol class="step-indicator" aria-label="Onboarding progress"><li :class="{active:step===1}">Details</li><li :class="{active:step===2}">Review</li><li :class="{active:step===3}">Complete</li></ol>
  <div v-if="error" class="alert alert-danger" role="alert">{{error}} No partial account was retained.</div>
  <form v-if="step===1" class="responsive-form" @submit.prevent="clearErrors();step=2" novalidate>
    <label v-for="field in fields" :key="field.key">{{field.label}}
      <input v-model="form[field.key]" class="form-control" :class="{'is-invalid':fieldErrors[field.key]}" :type="field.type||'text'" :autocomplete="field.type==='password'?'new-password':undefined" :required="field.required" :minlength="field.type==='password'?12:undefined">
      <span v-if="fieldErrors[field.key]" class="invalid-feedback">{{fieldErrors[field.key][0]}}</span>
    </label>
    <button class="btn btn-primary">Review onboarding</button>
  </form>
  <section v-if="step===2" aria-labelledby="review-heading"><h2 id="review-heading">Confirm details</h2><p>The temporary password is never redisplayed after submission.</p><dl class="detail-grid"><div v-for="field in fields" :key="field.key"><dt>{{field.label}}</dt><dd>{{field.type==='password'?'••••••••••••':form[field.key]}}</dd></div></dl><div class="button-row"><button class="btn btn-outline-secondary" @click="step=1">Back</button><button class="btn btn-primary" :disabled="busy" @click="submit">{{busy?'Creating…':'Create Tenant and Shop'}}</button></div></section>
  <section v-if="step===3" class="success-panel" role="status"><h2>Shop onboarding complete</h2><dl class="detail-grid"><div><dt>Tenant</dt><dd>{{result.tenant_public_id}}</dd></div><div><dt>Shop</dt><dd>{{result.shop_public_id}}</dd></div><div><dt>Owner</dt><dd>{{result.owner_email}}</dd></div><div><dt>Platform address</dt><dd>{{result.hostname}}</dd></div><div><dt>Trial</dt><dd>30 days · Active</dd></div></dl></section>
  <section class="workspace" aria-labelledby="domain-operations"><div class="button-row"><div><div class="eyebrow">Recent MFA required</div><h2 id="domain-operations">Domain operations</h2></div><button class="btn btn-outline-secondary" @click="loadDomains">Refresh</button></div><p>Ownership verification and active TLS are enforced before activation. Every mutation requires a reason.</p><div class="record-grid"><article v-for="domain in domains" :key="domain.public_id" class="record-card"><strong class="break-all">{{domain.hostname}}</strong><span>{{domain.shop_name}} · {{domain.domain_type}}</span><span>DNS {{domain.verification_status}} · TLS {{domain.certificate_status||'pending'}} · {{domain.is_active?'Active':'Inactive'}} <b v-if="domain.is_primary">· Primary</b></span><label>Operational reason<input v-model="domainReason[domain.public_id]" class="form-control" required></label><div class="button-row"><button v-if="domain.domain_type==='CUSTOM'" class="btn btn-outline-success" :disabled="busy" @click="domainAction(domain,'tls',true)">TLS ready</button><button v-if="domain.domain_type==='CUSTOM'" class="btn btn-outline-danger" :disabled="busy" @click="domainAction(domain,'tls',false)">TLS failed</button><button v-if="domain.domain_type==='CUSTOM' && !domain.is_active" class="btn btn-primary" :disabled="busy" @click="domainAction(domain,'activate')">Activate</button><button v-if="domain.is_active && !domain.is_primary" class="btn btn-outline-primary" :disabled="busy" @click="domainAction(domain,domain.domain_type==='PLATFORM_SUBDOMAIN'?'fallback':'primary')">Make primary</button><button v-if="domain.domain_type==='CUSTOM' && domain.is_active && !domain.is_primary" class="btn btn-outline-danger" :disabled="busy" @click="domainAction(domain,'deactivate')">Deactivate</button></div></article></div></section>
  <section class="workspace" aria-labelledby="tenant-operations"><div class="button-row"><div><div class="eyebrow">Phase 1 operations · Recent MFA required</div><h2 id="tenant-operations">Tenant, Shop and subscriptions</h2></div><button class="btn btn-outline-secondary" @click="loadOperations">Refresh</button></div><div class="record-grid"><article v-for="tenant in tenants" :key="tenant.public_id" class="record-card operation-card"><header><strong>{{tenant.legal_or_business_name}}</strong><p>Tenant {{tenant.status}} · Shop {{tenant.shop_status}} · {{tenant.shop_name}}</p></header><dl class="detail-grid"><div><dt>Current</dt><dd>{{tenant.subscription.current_entitlement?.plan_name||'None'}}</dd></div><div><dt>Current window</dt><dd>{{tenant.subscription.current_entitlement ? tenant.subscription.current_entitlement.starts_at+' → '+tenant.subscription.current_entitlement.ends_at : 'READ_ONLY when lifecycle permits'}}</dd></div><div><dt>Active Staff</dt><dd>{{tenant.active_staff}}</dd></div><div><dt>Future periods</dt><dd>{{tenant.subscription.future_periods.length}}</dd></div></dl><details><summary>Periods and events</summary><h3>Future</h3><p v-if="!tenant.subscription.future_periods.length">None</p><div v-for="period in tenant.subscription.future_periods" class="timeline-item">{{period.plan_name}} · {{period.starts_at}} → {{period.ends_at}}</div><h3>History</h3><p v-if="!tenant.subscription.historical_periods.length">None</p><div v-for="period in tenant.subscription.historical_periods" class="timeline-item">{{period.plan_name}} · {{period.starts_at}} → {{period.ends_at}}</div><h3>Events</h3><div v-for="event in tenant.subscription.events" class="timeline-item">{{event.event_type}} · {{event.effective_at}} · {{event.reason}}</div></details><form class="responsive-form" @submit.prevent="subscriptionAction(tenant)"><label>Operation<select v-model="operationForm(tenant).operation" class="form-select"><option>ACTIVATE</option><option>RENEW</option><option>UPGRADE</option><option>DOWNGRADE</option><option>EXTEND</option></select></label><label>Plan<select v-model="operationForm(tenant).plan_code" class="form-select"><option>STARTER</option><option>GROWTH</option><option>TRIAL</option></select></label><label>Starts (UTC)<input v-model="operationForm(tenant).starts_at" type="datetime-local" class="form-control" required></label><label>Ends (UTC)<input v-model="operationForm(tenant).ends_at" type="datetime-local" class="form-control" required></label><label>Reference<input v-model="operationForm(tenant).external_reference" class="form-control" maxlength="120"></label><label>Reason<input v-model="operationForm(tenant).reason" class="form-control" maxlength="500" required></label><button class="btn btn-primary" :disabled="busy">Apply entitlement</button></form><div class="button-row"><button v-if="tenant.status==='ACTIVE'" class="btn btn-outline-warning" :disabled="busy" @click="lifecycle(tenant,'tenant','suspend')">Suspend Tenant</button><button v-if="tenant.status==='SUSPENDED'" class="btn btn-outline-success" :disabled="busy" @click="lifecycle(tenant,'tenant','reactivate')">Reactivate Tenant</button><button v-if="tenant.status!=='CLOSED'" class="btn btn-danger" :disabled="busy" @click="lifecycle(tenant,'tenant','close')">Close Tenant</button><button v-if="tenant.shop_status==='ACTIVE'" class="btn btn-outline-danger" :disabled="busy" @click="lifecycle(tenant,'shop','deactivate')">Deactivate Shop</button><button v-else class="btn btn-outline-success" :disabled="busy||tenant.status==='CLOSED'" @click="lifecycle(tenant,'shop','reactivate')">Reactivate Shop</button></div></article></div></section>
</div>
<?= $this->endSection() ?>
